def transform(grid):
    h, w = len(grid), len(grid[0])
    marker = next(v for row in grid for v in row if v != grid[0][0])
    out = [row[:] for row in grid]

    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == marker]
        if len(cols) >= 2:
            for c in range(min(cols), max(cols) + 1):
                if out[r][c] != marker:
                    out[r][c] = 3

    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        if len(rows) >= 2:
            for r in range(min(rows), max(rows) + 1):
                if out[r][c] != marker:
                    out[r][c] = 3

    return out
